~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .badilisha(/\s+/g, ' ')
    .punguza();
}

/**
 * Utafutaji wa usahihi wa hali ya juu na Injini ya Maswali ya Semantiki
 */
Hamisha Sentensi za utendakazi wa async(
  swali: kamba,
  vichujio: SearchFilterOptions = {}
): Ahadi<{matokeo: SentenceItem[]; jumla:idadi; semanticMatch?: SemanticExplanationMatch[] }> {
  const all = await loadSentences();
  const normalizedQuery = normalizeText(hoja);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').chujio(Boolean) : [];

  const {
    cefr = 'wote',
    sehemu = 'wote',
    kategoria = 'wote',
    subcategory = 'wote',
    sarufi = 'wote',
    utaratibu = 'wote',
    kikomo = 50,
    kukabiliana = 0,
  } = vichungi;

  // Kuchuja kupita
  acha kuchujwa = all.filter(s => {
    ikiwa (cefr !== 'wote' && s.cefr !== cefr) itarudi sivyo;
    ikiwa (sehemu !== 'yote' && s.section !==section) itarudisha sivyo;
    ikiwa (kitengo !== 'yote' && s.category !== kategoria) itarudisha sivyo;
    ikiwa (kijamii !== 'yote' && s.kijamii !== kategoria ndogo) itarudisha sivyo;
    ikiwa (sarufi !== 'yote' && !s.grammar.toLowerCase().pamoja na(sarufi.toLowerCase())) itarudisha sivyo;
    ikiwa (urasmi !== 'wote' && s.formality.toLowerCase() !== formality.toLowerCase()) itarudi sivyo;
    kurudi kweli;
  });

  ikiwa (!normalizedQuery) {
    const total = filtered.length;
    const paginated = kuchujwa. kipande (kukabiliana, kukabiliana + na kikomo);
    rudisha {matokeo: yaliyowekwa alama, jumla };
  }

  // Algorithm ya alama
  interfaceScoredItem {
    bidhaa:SentensiItem;
    alama: nambari;
    kipengele: SemanticExplanationMatch['matchedAspect'];
  }

  const alifunga: ScoredItem[] = [];

  kwa (const s ya kuchujwa) {
    acha alama = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'kiingereza';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.purpose);

    // Ulinganifu kamili wa sentensi
    ikiwa (normEn === normalizedQuery) {
      alama += 100;
      matchedAspect = 'kiingereza';
    } vinginevyo ikiwa (normEg === normalizedQuery) {
      alama += 95;
      matchedAspect = 'arabic-eg';
    } vinginevyo ikiwa (normFusha === normalizedQuery) {
      alama += 90;
      matchedAspect = 'arabic-fusha';
    }

    //Substring ina
    ikiwa (normEn.includes(normalizedQuery)) {
      alama += 50;
      matchedAspect = 'kiingereza';
    } vinginevyo ikiwa (normEg.includes(normalizedQuery)) {
      alama += 45;
      matchedAspect = 'arabic-eg';
    } vinginevyo ikiwa (normFusha.includes(normalizedQuery)) {
      alama += 40;
      matchedAspect = 'arabic-fusha';
    } vinginevyo ikiwa (normGrammar.includes(normalizedQuery)) {
      alama += 35;
      matchedAspect = 'sarufi';
    } vinginevyo ikiwa (normPurpose.includes(normalizedQuery)) {
      alama += 30;
      matchedAspect = 'dhana';
    }

    // Mechi ya ishara
    basi tokenMatches = 0;
    kwa (const token of queryTokens) {
      ikiwa (normEn.includes(token)) tokenMatches += 5;
      ikiwa (normEg.includes(token)) tokenMatches += 4;
      ikiwa (normFusha.includes(token)) tokenMatches += 3;
      ikiwa (s.vocabulary.some(v => normalizeText(v).inajumuisha(ishara))) tokeniInayolingana += 4;
      ikiwa (s.tags.some(t => normalizeText(t).inajumuisha(ishara))) tokeniInayolingana += 3;
    }
    alama += tokenMatches;

    ikiwa (alama > 0) {
      score.push({ item: s, alama, kipengele: matchedAspect });
    }
  }

  alama.panga((a, b) => b.alama - a.alama);

  // Maelezo ya kisemantiki yanalingana kwa vitu vya juu
  const semanticMatches: SemanticExplanationMatch[] = score.slice(0, 5).map(s => {
    acha nuance = '';
    ikiwa (s.item.grammar.toLowerCase().inajumuisha('past continuous')) {
      nuance = 'The past continuous tense inaonyesha kwamba tukio lilikuwa likiendelea katika kipindi fulani cha wakati huko nyuma.';
    } vinginevyo ikiwa (s.item.grammar.toLowerCase().inajumuisha('present perfect continuous')) {
      nuance = 'Wakati uliopo kamili unaoendelea unasisitiza muda kutoka wakati uliopita na kuendelea hadi wakati wa kuzungumza.';
    } vinginevyo ikiwa (s.item.grammar.toLowerCase().inajumuisha('future perfect')) {
      nuance = 'Wakati ujao timilifu unaonyesha kwamba tukio litakamilika kabla ya muda maalum katika siku zijazo.';
    } vinginevyo ikiwa (s.item.grammar.toLowerCase().pamoja na('indirect')) {
      nuance = 'Aina ya ombi lisilo la moja kwa moja ni kilele cha adabu za kidiplomasia katika mawasiliano ya Kiingereza.';
    }
    kurudi {
      sentensi: s.kipengee,
      kufananaAlama: Math.min(100, alama),
      nuanceExplanationAr: nuance,
      Kipengele kinacholingana: kipengele,
    };
  });

  const jumla = alifunga. urefu;
  const paginated = score.slice(offset, offset + limit).map(s => s.item);

  kurudi {
    matokeo: paginated,
    jumla,
    mechi za semantic,
  };
}

/**
 * Sentensi ya Kila Siku ya Kuamua (Inafanana kwa watumiaji wote kwa siku yoyote)
 */
safirisha kazi ya async getDailySentence(): Promise<SentenceItem | null> {
  const all = await loadSentences();
  ikiwa (wote. urefu === 0) kurudi null;

  const leo = Tarehe mpya ();
  const dayOfYear = Math.floor(
    (leo.getTime() - Tarehe mpya(leo.getFullYear(), 0, 0).getTime()) / 1000 / 60/60/24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  rudisha zote[index] || zote[0];
}

