/**
 * Pata sentensi bila mpangilio, CEFR ya hiari au kichungi cha Sehemu
 */
safirisha kazi ya async getRandomSentence(cefr?: CEFRLevel, sehemu?: string): Promise<SentenceItem | null> {
  const all = await loadSentences();
  let pool = wote;
  ikiwa (cefr) {
    bwawa = bwawa.chujio(s => s.cefr === cefr);
  }
  ikiwa (sehemu) {
    bwawa = bwawa. chujio (s => s. sehemu === sehemu);
  }
  ikiwa (pool. urefu === 0) kurudi null;
  const randIdx = Math.floor(Math.random() * pool.length);
  bwawa la kurudi[randIdx];
}
